<?php
namespace App\Services;
use App\Models\Booking;
use App\Models\AdminNotification;
use App\Models\SmtpSetting;
use Illuminate\Support\Facades\Log;
use Illuminate\Support\Facades\Mail;
use App\Services\JorsidMailService;
use Throwable;
class BookingNotificationService
{
 private function tr(string $lang,string $de,string $fr,string $en):string{return match($lang){'fr'=>$fr,'en'=>$en,default=>$de};}
 public function newBooking(Booking $booking):void
 {
  $booking->loadMissing('service');$lang=in_array($booking->customer_language,['de','fr','en'],true)?$booking->customer_language:'de';
  AdminNotification::create(['booking_id'=>$booking->id,'type'=>'new_booking','title'=>'Nouvelle demande de rendez-vous','message'=>sprintf('%s a demandé %s le %s à %s.',$booking->customer_name,$booking->service?->name??'une prestation',$booking->appointment_date->format('d/m/Y'),substr($booking->appointment_time,0,5))]);
  $adminEmail=trim((string)(SmtpSetting::query()->value('admin_notification_email') ?: config('jorsid.admin_email')));$adminLang=(string)config('jorsid.admin_language','de');$details=$this->details($booking,$lang);
  if($adminEmail!==''){$this->send($adminEmail,(string)config('jorsid.admin_name','Kessy'),$this->tr($adminLang,'Neue Terminanfrage — Jorsid Beauty','Nouvelle demande de rendez-vous — Jorsid Beauty','New appointment request — Jorsid Beauty'),$this->tr($adminLang,"Hallo ".config('jorsid.admin_name','Kessy').",\n\nEine neue Terminanfrage ist eingegangen. Sie wartet auf Ihre Bestätigung.\n\n","Bonjour ".config('jorsid.admin_name','Kessy').",\n\nUne nouvelle demande de rendez-vous vient d’être reçue. Elle est en attente de votre confirmation.\n\n","Hello ".config('jorsid.admin_name','Kessy').",\n\nA new appointment request has arrived and is waiting for your confirmation.\n\n").$this->details($booking,$adminLang)."\n\n".$this->tr($adminLang,'Bitte öffnen Sie die Administration, um den Termin zu bestätigen, abzulehnen oder zu stornieren.','Connectez-vous à l’administration pour confirmer, refuser ou annuler le rendez-vous.','Open the admin area to confirm, reject or cancel the appointment.'),$booking,$adminLang);}else{Log::warning('Jorsid admin email is not configured; booking alert email skipped.',['booking_id'=>$booking->id]);}
  $subject=$this->tr($lang,'Terminanfrage erhalten — Jorsid Beauty','Demande de réservation reçue — Jorsid Beauty','Appointment request received — Jorsid Beauty');
  $body=$this->tr($lang,"Hallo {$booking->customer_name},\n\nwir haben Ihre Terminanfrage erhalten. Dies ist noch keine Bestätigung; Kessy prüft zuerst die tatsächliche Verfügbarkeit.\n\n","Bonjour {$booking->customer_name},\n\nNous avons bien reçu votre demande de rendez-vous. Ce message confirme la réception de la demande, pas encore le rendez-vous : Kessy doit d’abord vérifier les disponibilités.\n\n","Hello {$booking->customer_name},\n\nWe have received your appointment request. This is not a confirmation yet; Kessy must first check actual availability.\n\n").$details."\n\n".$this->tr($lang,'Sie erhalten eine weitere E-Mail, sobald sich der Status ändert.','Vous recevrez un autre e-mail dès que le statut changera.','You will receive another email when the status changes.')."\n\n".$this->tr($lang,'Vielen Dank,','Merci,','Thank you,')."\n".config('jorsid.business_name');
  $this->send($booking->customer_email,$booking->customer_name,$subject,$body,$booking,$lang);
 }
 public function statusChanged(Booking $booking,string $previousStatus):void
 {
  $booking->loadMissing('service');$lang=in_array($booking->customer_language,['de','fr','en'],true)?$booking->customer_language:'de';
  $messages=['confirmed'=>['Votre rendez-vous est confirmé — Jorsid Beauty','CONFIRMÉ','Votre rendez-vous est maintenant confirmé.','Ihr Termin ist bestätigt — Jorsid Beauty','BESTÄTIGT','Ihr Termin ist jetzt bestätigt.','Your appointment is confirmed — Jorsid Beauty','CONFIRMED','Your appointment is now confirmed.'],'rejected'=>['Réponse à votre demande — Jorsid Beauty','REFUSÉ','Nous sommes désolés, votre demande n’a pas pu être acceptée.','Antwort auf Ihre Terminanfrage — Jorsid Beauty','ABGELEHNT','Leider konnte Ihre Terminanfrage nicht angenommen werden.','Reply to your request — Jorsid Beauty','DECLINED','We are sorry, your request could not be accepted.'],'cancelled'=>['Annulation de votre rendez-vous — Jorsid Beauty','ANNULÉ','Votre rendez-vous a été annulé.','Terminabsage — Jorsid Beauty','STORNIERT','Ihr Termin wurde storniert.','Appointment cancelled — Jorsid Beauty','CANCELLED','Your appointment has been cancelled.'],'completed'=>['Rendez-vous terminé — Jorsid Beauty','TERMINÉ','Votre rendez-vous a été marqué comme terminé.','Termin abgeschlossen — Jorsid Beauty','ABGESCHLOSSEN','Ihr Termin wurde als abgeschlossen markiert.','Appointment completed — Jorsid Beauty','COMPLETED','Your appointment has been marked completed.'],'no_show'=>['Mise à jour de rendez-vous — Jorsid Beauty','ABSENCE','Le rendez-vous a été marqué comme non honoré.','Terminstatus aktualisiert — Jorsid Beauty','NICHT ERSCHIENEN','Der Termin wurde als nicht wahrgenommen markiert.','Appointment update — Jorsid Beauty','NO-SHOW','The appointment was marked as a no-show.']];
  if(!isset($messages[$booking->status]))return;$i=match($lang){'fr'=>0,'en'=>6,default=>3};$set=$messages[$booking->status];$subject=$set[$i];$label=$set[$i+1];$message=$set[$i+2];
  AdminNotification::create(['booking_id'=>$booking->id,'type'=>'booking_status','title'=>'Statut du rendez-vous modifié','message'=>$booking->reference.' : '.$previousStatus.' → '.$booking->status]);
  $body=$this->tr($lang,"Hallo {$booking->customer_name},\n\n{$message}\n\n","Bonjour {$booking->customer_name},\n\n{$message}\n\n","Hello {$booking->customer_name},\n\n{$message}\n\n").$this->details($booking,$lang)."\n".$this->tr($lang,'Status : ','Statut : ','Status: ').$label."\n\n".($booking->admin_note?$this->tr($lang,'Nachricht von Kessy:','Message de Kessy :','Message from Kessy:')."\n{$booking->admin_note}\n\n":'').$this->tr($lang,'Viele Grüße,','Cordialement,','Kind regards,')."\n".config('jorsid.business_name');$this->send($booking->customer_email,$booking->customer_name,$subject,$body,$booking,$lang);
  $adminEmail=trim((string)(SmtpSetting::query()->value('admin_notification_email') ?: config('jorsid.admin_email')));if($adminEmail!==''){$al=(string)config('jorsid.admin_language','de');$this->send($adminEmail,(string)config('jorsid.admin_name','Kessy'),$this->tr($al,'Terminstatus geändert — ','Statut modifié — ','Appointment status changed — ').$booking->reference,$this->tr($al,'Der Terminstatus wurde von ','Le statut du rendez-vous est passé de ','The appointment status changed from ').$previousStatus.$this->tr($al,' zu ',' à ',' to ').$booking->status."\n\n".$this->details($booking,$al),$booking,$al);}
 }
 private function details(Booking $b,string $lang):string
 {
  $mode=$b->service_mode==='home'?$this->tr($lang,'Hausbesuch — ','À domicile — ','Home visit — ').$b->address_line.', '.$b->postal_code.' '.$b->city.($b->address_note?' ('.$b->address_note.')':''):$this->tr($lang,'Im Salon','Au salon','At the salon');
  return $this->tr($lang,'Referenz','Référence','Reference').": {$b->reference}\n".$this->tr($lang,'Kundin','Cliente','Customer').": {$b->customer_name}\nE-mail: {$b->customer_email}\n".$this->tr($lang,'Telefon','Téléphone','Phone').": {$b->customer_phone}\n".$this->tr($lang,'Leistung','Prestation','Service').': '.($b->service?->name??'—')."\n".$this->tr($lang,'Datum','Date','Date').': '.$b->appointment_date->format('d/m/Y')."\n".$this->tr($lang,'Uhrzeit','Heure','Time').': '.substr($b->appointment_time,0,5).' – '.($b->ends_at?substr($b->ends_at,0,5):'—')."\n".$this->tr($lang,'Ort','Lieu','Location').": {$mode}\n".$this->tr($lang,'Leistungspreis','Prix prestation','Service price').': '.number_format((float)$b->service_price,2,',',' ' )." €\n".$this->tr($lang,'Anfahrt','Déplacement','Travel fee').': '.number_format((float)$b->travel_fee,2,',',' ' )." €\n".$this->tr($lang,'Geschätzter Gesamtpreis','Total estimé','Estimated total').': '.number_format((float)$b->total_price,2,',',' ' ).' €'.($b->customer_note?"\n".$this->tr($lang,'Notiz der Kundin','Note de la cliente','Customer note').": {$b->customer_note}":'');
 }
 private function send(string $email,string $name,string $subject,string $body, ?Booking $booking = null, string $language = 'de'):void{try{app(JorsidMailService::class)->send($email,$name,$subject,$body,$booking,$language);}catch(Throwable $e){Log::error('Jorsid booking email failed',['recipient'=>$email,'subject'=>$subject,'error'=>$e->getMessage()]);}}
}
